export const GLOSSARY_SHARD = Object.freeze({"altcoin":{"slug":"altcoin","cat":"basics","en":"Altcoin","contentLocale":"id","term":"Altcoin","aka":["alt","koin alternatif"],"short":"Altcoin adalah sebutan untuk semua aset kripto selain Bitcoin, mulai dari jaringan besar seperti Ethereum dan Solana hingga token kecil yang baru diluncurkan.","body":[["Istilah ini berasal dari alternative coin. Awalnya dipakai untuk koin yang meniru ",["Bitcoin","bitcoin"],", kini maknanya mencakup hampir semua kripto lain: koin ",["layer 1","layer-1"],", token ",["DeFi","defi"],", token gim, ",["memecoin","memecoin"],", dan lain-lain. Sebagian trader tidak menghitung ",["stablecoin","stablecoin"]," sebagai altcoin karena tujuannya berbeda."],["Altcoin umumnya lebih volatil daripada Bitcoin. Kapitalisasi pasarnya lebih kecil, likuiditasnya lebih tipis, dan harganya sering bergerak lebih tajam saat ",["pasar naik","bull-market"]," maupun turun. Ada juga istilah altseason, yaitu periode ketika banyak altcoin naik lebih kencang daripada BTC."],"Sebelum membeli altcoin, periksa kegunaan jaringannya, tokenomics, jadwal token unlock, dan di exchange mana saja ia diperdagangkan. Likuiditas yang tipis berarti selisih harga beli dan jual bisa lebar dan slippage besar."],"example":"Misalkan pasar sedang turun dan BTC melemah 10% dalam seminggu. Sebuah altcoin kecil yang Anda pegang turun 35% di periode yang sama. Jika Anda memiliki altcoin senilai 400 USDT, nilainya menjadi 260 USDT. Untuk kembali ke 400 USDT, harga altcoin itu perlu naik sekitar 54%, bukan 35%, karena kenaikan dihitung dari harga yang sudah lebih rendah.","mistakes":["Membeli altcoin hanya karena harga per koinnya kecil, tanpa melihat kapitalisasi pasar dan jumlah suplai.","Mengabaikan jadwal token unlock yang bisa menambah suplai di pasar dalam jumlah besar.","Menyebar dana ke puluhan altcoin kecil lalu tidak sanggup memantau semuanya."],"faq":[{"q":"Apakah Ethereum termasuk altcoin?","a":"Secara definisi ya, karena Ethereum bukan Bitcoin. Namun karena ukurannya besar, banyak orang membahasnya sebagai kategori tersendiri."},{"q":"Apa itu altseason?","a":"Altseason adalah periode ketika banyak altcoin naik lebih cepat daripada Bitcoin. Tidak ada tanggal pasti kapan terjadi, dan periodenya bisa sangat singkat."}],"title":"Apa itu altcoin? Arti dan risikonya","description":"Arti altcoin, kenapa harganya lebih bergejolak daripada Bitcoin, dan apa yang perlu dicek sebelum membeli koin alternatif.","related":[["bitcoin","Bitcoin (BTC)","Bitcoin (BTC) adalah aset kripto pertama yang diluncurkan pada 2009, berjalan di jaringan terdesentralisasi dengan proof of work dan jumlah maksimal 21 juta koin."],["memecoin","Memecoin (koin meme)","Memecoin adalah aset kripto yang nilainya terutama digerakkan oleh budaya internet, komunitas, dan tren media sosial, bukan oleh kegunaan teknis atau pendapatan proyek."],["market-capitalization","Market capitalization (kapitalisasi pasar)","Market capitalization atau kapitalisasi pasar adalah nilai total sebuah aset kripto yang beredar, dihitung dari harga saat ini dikali jumlah suplai yang beredar."],["token-listing","Listing token","Listing token adalah proses ketika bursa menambahkan token baru ke daftar aset yang bisa disetor dan diperdagangkan, biasanya diumumkan lebih dulu beserta jadwal pembukaan setoran dan perdagangan."],["volatility","Volatility (volatilitas)","Volatilitas adalah ukuran seberapa besar dan seberapa cepat harga sebuah aset bergerak naik turun dalam periode tertentu."]],"lesson":null,"coin":{"slug":"solana","name":"Solana","symbol":"SOL"},"tool":"/coins","cta":false},"layer-2":{"slug":"layer-2","cat":"basics","en":"Layer 2 (L2)","contentLocale":"id","term":"Layer 2 (L2)","aka":["L2","rollup"],"short":"Layer 2 (L2) adalah jaringan yang dibangun di atas blockchain layer 1, memproses transaksi di luar jaringan utama lalu menyetor ringkasannya ke L1 agar lebih cepat dan murah.","body":[["Sebagian besar L2 ",["Ethereum","ethereum"]," memakai teknologi rollup. Ribuan transaksi digabung menjadi satu paket, lalu data atau buktinya dikirim ke Ethereum. Karena biaya L1 dibagi ke banyak pengguna, biaya per transaksi turun jauh. Contoh L2 Ethereum yang dikenal adalah Arbitrum, Optimism, Base, zkSync, dan Starknet."],"Ada dua jenis rollup utama. Optimistic rollup menganggap transaksi sah kecuali dibantah dalam periode tantangan, sehingga penarikan langsung ke L1 lewat bridge resmi bisa memakan sekitar tujuh hari. ZK rollup memakai bukti kriptografi sehingga finalisasinya bisa lebih cepat.",[["Bitcoin","bitcoin"]," juga punya solusi lapisan kedua seperti Lightning Network. Saat menarik dari exchange, Anda sering bisa memilih jaringan L2 secara langsung. Pastikan dompet atau alamat tujuan mendukung jaringan yang sama."]],"example":["Misalkan Anda ingin swap token senilai 200 ",["USDC","usdc"],". Di jaringan utama Ethereum, ",["biaya gas","gas-fee"]," saat ramai bisa mencapai 6 USDC, atau 3% dari transaksi. Di sebuah L2, biaya swap yang sama mungkin hanya 0,05 USDC, atau 0,025%. Jika Anda melakukan 20 swap dalam sebulan, selisihnya sekitar 120 USDC dibanding sekitar 1 USDC. Angka biaya ini ilustrasi dan bisa berubah setiap saat."],"mistakes":["Menarik ETH lewat jaringan Arbitrum ke alamat exchange yang hanya menerima jaringan utama Ethereum.","Tidak tahu bahwa penarikan dari optimistic rollup lewat bridge resmi bisa memakan waktu sekitar seminggu.","Menganggap semua L2 sama aman, padahal tingkat desentralisasi sequencer dan sistem buktinya berbeda."],"faq":[{"q":"Apakah ETH di Arbitrum sama dengan ETH di Ethereum?","a":"Nilainya sama karena bisa ditukar kembali lewat bridge, tetapi secara teknis berada di jaringan berbeda. Anda harus memakai jaringan yang benar saat mengirim."},{"q":"Kenapa biaya layer 2 lebih murah?","a":"Karena banyak transaksi digabung menjadi satu paket sebelum dikirim ke layer 1, sehingga biaya L1 dibagi ke banyak pengguna."}],"title":"Apa itu layer 2 (L2)? Arti rollup dan contohnya","description":"Arti layer 2, cara rollup membuat transaksi lebih murah, contoh L2 Ethereum, dan hal yang perlu dicek saat transfer.","related":[["layer-1","Layer 1 (L1)","Layer 1 (L1) adalah blockchain dasar yang memproses dan memfinalisasi transaksinya sendiri dengan mekanisme konsensus dan koin aslinya, seperti Bitcoin, Ethereum, dan Solana."],["gas-fee","Gas fee (biaya gas)","Gas fee atau biaya gas adalah biaya yang Anda bayar kepada jaringan blockchain untuk memproses transaksi atau menjalankan smart contract, biasanya dalam coin asli jaringan tersebut."],["cross-chain-bridge","Cross-chain bridge (jembatan antar-chain)","Cross-chain bridge adalah protokol yang memindahkan aset atau data dari satu blockchain ke blockchain lain, misalnya memindahkan USDC dari Ethereum ke Arbitrum."],["ethereum","Ethereum (ETH)","Ethereum adalah blockchain yang bisa menjalankan smart contract, dan ETH adalah koin aslinya yang dipakai untuk membayar biaya gas dan untuk staking."],["blockchain-network","Jaringan deposit (pilihan chain)","Jaringan deposit adalah blockchain yang Anda pilih untuk mengirim atau menerima sebuah aset, misalnya USDT lewat Tron, Ethereum, atau BNB Smart Chain, dan pilihan ini harus sama di sisi pengirim dan penerima."]],"lesson":null,"coin":{"slug":"arbitrum","name":"Arbitrum","symbol":"ARB"},"tool":null,"cta":false},"spot-trading":{"slug":"spot-trading","cat":"trading","en":"Spot trading","contentLocale":"id","term":"Spot trading (perdagangan spot)","aka":["spot","pasar spot","trading spot"],"short":"Spot trading adalah jual beli aset kripto secara langsung di harga pasar saat ini, di mana aset benar-benar berpindah ke akun Anda setelah transaksi selesai.","body":[["Saat Anda membeli ",["BTC","bitcoin"]," di pasar spot dengan ",["USDT","usdt"],", BTC itu langsung menjadi milik Anda dan bisa ditarik ke ",["dompet pribadi","non-custodial-wallet"],". Ini berbeda dengan futures, di mana Anda hanya memegang kontrak yang mengikuti harga tanpa memiliki asetnya."],["Di pasar spot tanpa margin, kerugian maksimal Anda adalah dana yang Anda belikan. Tidak ada ",["likuidasi","liquidation"]," dan tidak ada ",["funding rate","funding-rate"],". Karena itu spot trading biasanya menjadi titik awal yang paling sederhana bagi pemula."],["Transaksi spot dilakukan dengan ",["market order","market-order"]," untuk eksekusi cepat atau limit order untuk harga tertentu. Biaya trading dikenakan setiap transaksi, dan besarannya berbeda antar exchange serta bergantung pada apakah Anda maker atau taker."]],"example":"Misalkan Anda membeli 0,5 ETH di harga 3.000 USDT, total 1.500 USDT, dengan biaya taker 0,1% atau 1,50 USDT. Jika ETH naik ke 3.300 USDT dan Anda menjual 0,5 ETH, Anda menerima 1.650 USDT dikurangi biaya 1,65 USDT. Keuntungan bersih sekitar 1.650 - 1,65 - 1.500 - 1,50 = 146,85 USDT. Jika ETH turun 50%, kerugian Anda 750 USDT tetapi posisi tidak dilikuidasi.","mistakes":["Lupa menghitung biaya beli dan jual saat menghitung keuntungan.","Mengira spot trading bebas risiko, padahal harga aset tetap bisa turun tajam.","Tidak sengaja masuk ke mode margin atau futures karena antarmuka aplikasi mirip."],"faq":[{"q":"Apa beda spot dan futures?","a":"Di spot Anda membeli aset yang sebenarnya. Di futures Anda memegang kontrak yang mengikuti harga, sering dengan leverage, sehingga bisa terkena likuidasi."},{"q":"Apakah spot trading bisa likuidasi?","a":"Spot biasa tanpa pinjaman margin tidak bisa dilikuidasi. Risiko likuidasi baru muncul jika Anda memakai margin atau futures."}],"title":"Apa itu spot trading? Arti perdagangan spot kripto","description":"Arti spot trading di kripto, bedanya dengan futures, cara menghitung untung rugi beserta biaya, dan risiko untuk pemula.","related":[["trading-pair","Trading pair (pasangan perdagangan)","Trading pair adalah dua aset yang diperdagangkan satu sama lain di exchange, seperti BTC/USDT, di mana harga aset pertama dinyatakan dalam satuan aset kedua."],["market-order","Market order","Market order adalah perintah membeli atau menjual segera di harga terbaik yang tersedia saat itu, sehingga eksekusinya cepat tetapi harga akhirnya tidak dijamin."],["limit-order","Limit order","Limit order adalah perintah membeli atau menjual di harga tertentu yang Anda tetapkan atau lebih baik, sehingga harga terkendali tetapi order belum tentu tereksekusi."],["perpetual-futures","Kontrak berjangka perpetual (perpetual futures)","Kontrak berjangka perpetual adalah kontrak futures tanpa tanggal jatuh tempo yang harganya dijaga tetap dekat dengan harga spot melalui pembayaran funding rate berkala antara posisi long dan short."],["order-book","Order book (buku order)","Order book adalah daftar real-time semua order beli dan order jual yang menunggu di sebuah pasangan perdagangan, disusun berdasarkan harga dan jumlahnya."]],"lesson":{"id":"E07","slug":"first-spot-trade","ep":7,"title":"Perdagangan spot pertamamu: dari 100 jadi 0.002 BTC"},"coin":null,"tool":"/compare","cta":true},"candlestick-chart":{"slug":"candlestick-chart","cat":"trading","en":"Candlestick chart","contentLocale":"id","term":"Grafik candlestick (candle)","aka":["candlestick","grafik lilin","chart candle"],"short":"Grafik candlestick adalah grafik harga yang menampilkan harga pembukaan, tertinggi, terendah, dan penutupan (OHLC) untuk setiap periode dalam bentuk batang menyerupai lilin.","body":["Setiap candle mewakili satu periode, misalnya 1 jam atau 1 hari. Badan candle menunjukkan jarak antara harga buka dan tutup. Garis tipis di atas dan bawah disebut sumbu atau shadow (sering juga disebut wick), yang menunjukkan harga tertinggi dan terendah selama periode itu.","Candle hijau berarti harga tutup lebih tinggi dari harga buka, sedangkan candle merah berarti harga turun. Perhatikan bahwa beberapa aplikasi di Asia memakai warna terbalik, dan Anda bisa mengubahnya di pengaturan. Badan panjang menandakan tekanan beli atau jual yang kuat; sumbu panjang menandakan harga sempat ditolak di level tertentu.",["Satu candle jarang cukup untuk mengambil keputusan. Trader biasanya membacanya bersama volume, ",["level support","support-and-resistance"]," dan resistance, serta beberapa timeframe sekaligus."]],"example":["Misalkan candle harian SOL dibuka di 140 ",["USDT","usdt"],", sempat naik ke 152, turun ke 136, lalu ditutup di 148. Badan candle berwarna hijau dari 140 ke 148, sepanjang 8 USDT. Sumbu atas dari 148 ke 152 sepanjang 4 USDT, dan sumbu bawah dari 140 ke 136 juga 4 USDT. Jadi rentang total hari itu 16 USDT atau sekitar 11% dari harga buka. Ini menunjukkan pembeli menguasai hari itu, tetapi sempat ada penjualan di dekat 152."],"mistakes":["Mengambil keputusan dari candle yang belum ditutup, padahal bentuknya masih bisa berubah total.","Hanya melihat timeframe 1 menit atau 5 menit yang penuh noise tanpa melihat gambaran harian.","Menghafal pola candle tanpa memperhatikan volume dan konteks tren."],"faq":[{"q":"Apa arti sumbu (wick) panjang pada candle?","a":"Sumbu panjang menunjukkan harga sempat bergerak jauh lalu ditolak dan kembali. Sumbu atas panjang menandakan tekanan jual di level tinggi, sumbu bawah panjang menandakan pembeli masuk di level rendah."},{"q":"Timeframe candle apa yang sebaiknya dipakai pemula?","a":"Pemula umumnya lebih mudah membaca timeframe 4 jam dan harian karena lebih sedikit noise. Timeframe kecil cocok untuk menentukan titik masuk setelah arah besar jelas."}],"title":"Apa itu grafik candlestick? Cara membaca candle kripto","description":"Belajar membaca grafik candlestick kripto: arti badan, sumbu, warna candle, dan cara memakai timeframe dengan benar.","related":[["support-and-resistance","Support dan resistance","Support dan resistance adalah area harga di mana penurunan cenderung tertahan karena banyak pembeli (support) atau kenaikan cenderung tertahan karena banyak penjual (resistance)."],["volatility","Volatility (volatilitas)","Volatilitas adalah ukuran seberapa besar dan seberapa cepat harga sebuah aset bergerak naik turun dalam periode tertentu."],["trading-volume","Volume trading (trading volume)","Volume trading adalah total nilai atau jumlah aset yang diperdagangkan dalam periode tertentu, misalnya 24 jam, dan dipakai untuk mengukur seberapa aktif sebuah pasar."],["all-time-high","All-time high (ATH)","All-time high (ATH) adalah harga tertinggi yang pernah dicapai sebuah aset sejak mulai diperdagangkan."]],"lesson":{"id":"E15","slug":"read-a-candlestick","ep":15,"title":"Satu candle: apa empat hal yang disampaikannya kepada Anda?"},"coin":null,"tool":null,"cta":false},"last-price":{"slug":"last-price","cat":"derivatives","en":"Last traded price","contentLocale":"id","term":"Harga terakhir (last traded price)","aka":["last price","harga transaksi terakhir","harga pasar"],"short":"Harga terakhir adalah harga transaksi paling akhir yang benar-benar terjadi di order book sebuah exchange, dan biasanya inilah angka yang Anda lihat di grafik dan daftar pasar.","body":["Setiap kali order beli dan jual bertemu, transaksi tercatat dan harga terakhir diperbarui. Di pasar likuid, harga terakhir bergerak sangat halus. Di pasar tipis, satu order besar bisa membuat harga terakhir melompat jauh dalam sekejap, lalu kembali.",["Harga terakhir berbeda dari ",["mark price","mark-price"]," dan ",["harga indeks","index-price"],". ",["Grafik candlestick","candlestick-chart"]," di exchange biasanya memakai harga terakhir, sehingga wick panjang di grafik tidak selalu berarti mark price juga bergerak sejauh itu."],["Harga terakhir juga tidak sama dengan harga eksekusi Anda. ",["Market order","market-order"]," Anda akan terisi pada harga ask terbaik untuk beli atau bid terbaik untuk jual, dan bisa merambat ke level berikutnya jika ukurannya besar. Saat memasang ",["stop loss","stop-loss"]," di futures, banyak exchange memberi pilihan pemicu: last price atau mark price."]],"example":["Harga terakhir DOGE di layar 0,1500 ",["USDT","usdt"],". Order book menunjukkan ask terbaik 0,1501 dengan 20.000 DOGE, lalu 0,1503 dengan 30.000 DOGE. Jika Anda membeli 50.000 DOGE dengan market order, 20.000 terisi di 0,1501 dan 30.000 di 0,1503. Total 3.002 + 4.509 = 7.511 USDT, harga rata-rata 0,15022. Itu sekitar 0,15% di atas harga terakhir yang Anda lihat sebelum menekan tombol beli."],"mistakes":["Mengira market order pasti terisi di harga terakhir yang tertera di layar.","Memakai pemicu last price untuk stop loss di pasar tipis sehingga mudah tersentuh oleh wick singkat.","Membandingkan harga terakhir antar-exchange tanpa memperhatikan spread dan likuiditas."],"faq":[{"q":"Sebaiknya stop loss memakai last price atau mark price?","a":"Mark price lebih tahan terhadap lonjakan singkat, sedangkan last price bereaksi lebih cepat terhadap transaksi nyata. Banyak trader futures memilih mark price untuk menghindari stop tersentuh oleh wick sesaat."},{"q":"Kenapa harga terakhir berbeda di tiap exchange?","a":"Setiap exchange punya order book sendiri. Harganya biasanya berdekatan karena arbitrase, tetapi bisa berbeda sedikit, terutama saat volatilitas tinggi."}],"title":"Apa itu last price? Arti harga terakhir di exchange kripto","description":"Pahami last price atau harga transaksi terakhir, bedanya dengan mark price dan harga eksekusi, serta pengaruhnya pada stop loss.","related":[["mark-price","Mark price (harga tanda)","Mark price adalah harga acuan yang dihitung exchange dari harga indeks beberapa exchange spot dan basis kontrak, dipakai untuk menghitung unrealized PnL dan memicu likuidasi pada kontrak futures."],["index-price","Harga indeks (index price)","Harga indeks adalah rata-rata tertimbang harga spot sebuah aset dari beberapa exchange besar, dipakai exchange sebagai acuan untuk mark price, funding rate, dan settlement kontrak futures."],["order-book","Order book (buku order)","Order book adalah daftar real-time semua order beli dan order jual yang menunggu di sebuah pasangan perdagangan, disusun berdasarkan harga dan jumlahnya."],["stop-loss","Stop loss","Stop loss adalah order otomatis untuk menutup posisi ketika harga bergerak melawan Anda sampai level tertentu, agar kerugian dibatasi sesuai rencana."]],"lesson":{"id":"E13","slug":"price-vs-fill-price","ep":13,"title":"Mengapa harga di layar bukan harga eksekusi saya?"},"coin":null,"tool":null,"cta":false},"funding-rate-arbitrage":{"slug":"funding-rate-arbitrage","cat":"derivatives","en":"Funding rate arbitrage","contentLocale":"id","term":"Arbitrase funding rate (funding rate arbitrage)","aka":["funding arbitrage","arbitrase funding","cash and carry perpetual"],"short":"Arbitrase funding rate adalah strategi netral pasar yang membeli aset di spot dan membuka short dengan ukuran sama di perpetual, sehingga risiko harga saling meniadakan dan keuntungan berasal dari pembayaran funding.","body":[["Saat ",["funding rate","funding-rate"]," positif, pemegang short menerima pembayaran dari pemegang long. Dengan memegang spot sekaligus short ",["perpetual","perpetual-futures"],", pergerakan harga hampir tidak memengaruhi nilai gabungan, sementara funding terus masuk setiap periode settlement. Variasi lain memanfaatkan selisih funding rate antar-exchange untuk aset yang sama."],["Hasilnya tidak tetap. Funding rate berubah setiap periode dan bisa berbalik negatif, sehingga posisi short justru membayar. Biaya masuk dan keluar posisi di dua pasar, yaitu ",["biaya trading","maker-taker-fees"]," dan spread, juga mengurangi hasil, jadi strategi ini biasanya hanya masuk akal jika dipegang cukup lama."],"Risiko lain yang sering diabaikan: posisi short bisa dilikuidasi jika harga melonjak dan margin di akun futures tidak cukup, meskipun spotnya untung. Ada pula risiko platform, terutama jika spot dan futures berada di exchange berbeda. Interval funding dan batasnya berbeda di tiap exchange."],"example":["Anda membeli 1 ",["BTC","bitcoin"]," spot di 60.000 ",["USDT","usdt"]," dan short 1 BTC perpetual dengan margin 20.000 USDT (3x). Funding rata-rata 0,015% per 8 jam. Setiap periode Anda menerima 60.000 x 0,015% = 9 USDT, atau 27 USDT per hari. Dalam 30 hari, sekitar 810 USDT. Biaya masuk dan keluar di kedua pasar misalnya 0,1% x 60.000 x 4 transaksi = 240 USDT, sehingga hasil bersih sekitar 570 USDT dari modal 80.000 USDT, sekitar 0,7% sebulan, jika funding tidak berubah."],"mistakes":["Menganggap funding rate hari ini akan tetap sama selama berminggu-minggu.","Memakai leverage tinggi di sisi short sehingga posisi dilikuidasi saat harga naik tajam.","Lupa menghitung biaya trading dan spread untuk masuk dan keluar di dua pasar."],"faq":[{"q":"Apakah arbitrase funding rate bebas risiko?","a":"Tidak. Ada risiko funding berbalik negatif, likuidasi pada sisi short, perbedaan harga eksekusi, dan risiko exchange. Strateginya netral terhadap harga, bukan bebas risiko."},{"q":"Berapa modal yang dibutuhkan untuk arbitrase funding?","a":"Anda butuh modal untuk membeli spot penuh ditambah margin untuk posisi short. Karena itu hasil dalam persen per modal biasanya lebih kecil daripada angka funding rate itu sendiri."}],"title":"Apa itu arbitrase funding rate? Cara kerja dan risikonya","description":"Pelajari arbitrase funding rate: kombinasi spot dan short perpetual, cara menghitung hasil setelah biaya, serta risiko likuidasi dan funding.","related":[["funding-rate","Funding rate","Funding rate adalah pembayaran berkala antara trader posisi long dan short di kontrak perpetual yang menjaga harga kontrak tetap dekat dengan harga spot."],["arbitrage","Arbitrase (arbitrage)","Arbitrase adalah strategi memanfaatkan selisih harga aset yang sama di dua pasar berbeda, misalnya membeli di exchange yang lebih murah dan menjual di exchange yang lebih mahal secara bersamaan."],["hedging","Hedging (lindung nilai)","Hedging adalah strategi membuka posisi yang berlawanan dengan aset atau posisi yang Anda pegang untuk mengurangi risiko kerugian akibat pergerakan harga, dengan konsekuensi potensi untungnya ikut berkurang."],["perpetual-futures","Kontrak berjangka perpetual (perpetual futures)","Kontrak berjangka perpetual adalah kontrak futures tanpa tanggal jatuh tempo yang harganya dijaga tetap dekat dengan harga spot melalui pembayaran funding rate berkala antara posisi long dan short."]],"lesson":{"id":"E24","slug":"funding-fees-final","ep":24,"title":"Harga datar, saldo turun? Selesaikan level terakhir dengan mengingat biaya"},"coin":null,"tool":"/funding-rates","cta":false},"hardware-wallet":{"slug":"hardware-wallet","cat":"wallets-security","en":"Hardware wallet","contentLocale":"id","term":"Hardware wallet (dompet perangkat keras)","aka":["dompet hardware","dompet perangkat keras","hardware wallet"],"short":"Hardware wallet adalah perangkat fisik khusus yang menyimpan private key secara offline dan menandatangani transaksi di dalam perangkat, sehingga kunci tidak pernah terekspos ke komputer atau ponsel.","body":["Merek yang dikenal antara lain Ledger, Trezor, dan Keystone. Perangkat ini dihubungkan lewat USB, Bluetooth, atau kode QR ke aplikasi pendamping. Aplikasi menyiapkan transaksi, lalu Anda memeriksa dan menyetujuinya dengan menekan tombol di perangkat itu sendiri.","Nilai utamanya ada pada layar perangkat. Malware di komputer bisa mengganti alamat tujuan di layar komputer, tetapi tidak bisa mengubah apa yang ditampilkan dan ditandatangani di dalam hardware wallet. Karena itu Anda wajib mencocokkan alamat dan jumlah di layar perangkat sebelum menekan setuju.",["Hardware wallet tetap memakai ",["seed phrase","seed-phrase"]," sebagai cadangan. Jika perangkat rusak atau hilang, aset bisa dipulihkan di perangkat baru. Belilah hanya dari toko resmi atau distributor resmi, karena perangkat bekas atau yang sudah dibuka bisa saja sudah dimanipulasi."]],"example":["Anda ingin mengirim 300 ",["USDC","usdc"]," ke teman. Di laptop, alamat tujuan diawali 0x7a3F dan diakhiri 91cE. Saat transaksi muncul di layar hardware wallet, ternyata alamatnya diakhiri 4d2B. Ini tanda malware mengganti alamat di clipboard. Anda menolak transaksi di perangkat, sehingga 300 USDC tetap aman, lalu memindai laptop dan menyalin ulang alamat dari sumber yang benar."],"mistakes":["Membeli hardware wallet bekas atau dari penjual tidak resmi yang menyertakan seed phrase sudah tercetak.","Menekan setuju di perangkat tanpa membaca alamat dan jumlah yang tampil di layarnya.","Mengira hardware wallet melindungi Anda dari kontrak berbahaya, padahal Anda tetap bisa menyetujui token approval yang merugikan."],"faq":[{"q":"Apakah hardware wallet bisa diretas?","a":"Serangan jarak jauh sangat sulit karena kunci tidak pernah keluar dari perangkat. Risiko yang lebih nyata adalah seed phrase bocor, perangkat palsu, atau Anda menyetujui transaksi berbahaya."},{"q":"Apakah hardware wallet perlu internet?","a":"Perangkatnya sendiri tidak terhubung internet. Aplikasi pendamping di komputer atau ponsel yang terhubung ke jaringan untuk mengirim transaksi yang sudah ditandatangani."}],"title":"Apa itu hardware wallet? Fungsi dan cara kerjanya","description":"Arti hardware wallet, cara perangkat ini menandatangani transaksi secara offline, dan hal yang wajib Anda periksa sebelum menyetujui transaksi.","related":[["cold-wallet","Cold wallet (cold storage)","Cold wallet adalah cara menyimpan kripto dengan private key yang dibuat dan disimpan sepenuhnya offline, sehingga tidak bisa dijangkau peretas lewat internet."],["seed-phrase","Seed phrase (frasa pemulihan)","Seed phrase adalah rangkaian 12 atau 24 kata acak yang menjadi cadangan utama dompet kripto, karena dari kata-kata inilah semua private key dan alamat dompet Anda bisa dibuat ulang."],["private-key","Private key (kunci privat)","Private key adalah angka rahasia yang membuktikan kepemilikan sebuah alamat kripto dan dipakai untuk menandatangani transaksi, sehingga siapa pun yang memegangnya bisa memindahkan aset di alamat itu."],["address-poisoning","Address poisoning (peracunan alamat)","Address poisoning adalah penipuan di mana pelaku mengirim transaksi bernilai kecil atau nol dari alamat yang mirip dengan alamat yang sering Anda pakai, berharap Anda menyalin alamat palsu itu dari riwayat transaksi."]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"Di mana koin saya? Bursa vs dompet"},"coin":null,"tool":null,"cta":false},"governance-token":{"slug":"governance-token","cat":"defi","en":"Governance token","contentLocale":"id","term":"Governance token (token tata kelola)","aka":["token tata kelola","token governance","token voting"],"short":"Governance token adalah token yang memberi pemegangnya hak suara atas keputusan sebuah protokol atau DAO, seperti perubahan parameter, penggunaan kas, atau peningkatan kontrak.","body":["Contoh yang dikenal adalah UNI untuk Uniswap, AAVE untuk Aave, dan ARB untuk Arbitrum. Biasanya berlaku prinsip satu token satu suara, dan Anda bisa memilih sendiri atau mendelegasikan suara kepada delegasi yang aktif mengikuti diskusi.",["Governance token sering dibagikan lewat ",["airdrop","airdrop"]," kepada pengguna awal, insentif ",["liquidity mining","yield-farming"],", alokasi tim dan investor, serta kas ",["DAO","dao"],". Karena itu, penting membaca ",["tokenomics","tokenomics"],": berapa persen dipegang tim dan investor, kapan masa penguncian (vesting) berakhir, dan berapa emisi baru setiap tahun."],["Hak suara tidak sama dengan hak atas pendapatan. Banyak governance token tidak memberi bagian dari fee protokol, sehingga nilainya sangat bergantung pada ekspektasi pasar. Beberapa protokol menambahkan fungsi lain seperti ",["staking","staking"]," atau pembagian fee, dan aturannya berbeda di setiap proyek."]],"example":"Misalnya Anda memegang 2.000 token tata kelola sebuah protokol dengan total suplai 1 miliar token, berarti 0,0002% dari suplai. Dalam voting terakhir hanya 40 juta token yang ikut memilih. Jika Anda ikut voting, suara Anda setara 2.000 dari 40.000.000 atau 0,005% suara yang masuk. Sementara itu, satu dana investor yang memegang 15 juta token bisa menyumbang lebih dari sepertiga suara dalam voting yang sama.","mistakes":["Membeli governance token dengan asumsi otomatis mendapat bagi hasil dari protokol.","Tidak memeriksa jadwal unlock token tim dan investor yang bisa menambah suplai beredar.","Mengklaim airdrop governance token di situs tidak resmi yang meminta seed phrase atau approval."],"faq":[{"q":"Apa fungsi governance token?","a":"Fungsi utamanya adalah memberi hak suara atas keputusan protokol. Beberapa token juga punya fungsi lain, seperti staking, tetapi itu tergantung desain masing-masing proyek."},{"q":"Apakah governance token sama dengan saham?","a":"Tidak. Saham memberi hak hukum atas perusahaan, sedangkan governance token umumnya hanya memberi hak suara di protokol dan tidak menjamin bagi hasil."}],"title":"Apa itu governance token? Arti token tata kelola","description":"Pelajari arti governance token, contoh seperti UNI dan AAVE, cara voting dan delegasi, serta beda hak suara dan hak pendapatan.","related":[["dao","DAO (organisasi otonom terdesentralisasi)","DAO adalah organisasi yang aturan dan keputusannya dijalankan lewat smart contract dan voting anggota, biasanya pemegang governance token, bukan melalui struktur manajemen tradisional."],["tokenomics","Tokenomics","Tokenomics adalah desain ekonomi sebuah token, mencakup jumlah suplai, cara distribusi, jadwal unlock, kegunaan token, dan mekanisme yang menambah atau mengurangi suplai."],["airdrop","Airdrop","Airdrop adalah pembagian token gratis oleh sebuah proyek kripto ke alamat dompet tertentu, biasanya untuk pengguna awal, pemegang token tertentu, atau sebagai promosi."],["coin-vs-token","Coin vs token","Coin adalah aset asli sebuah blockchain yang dipakai untuk membayar biaya jaringan, sedangkan token adalah aset yang dibuat di atas blockchain lain melalui smart contract."]],"lesson":null,"coin":{"slug":"uniswap","name":"Uniswap","symbol":"UNI"},"tool":null,"cta":false},"usdt":{"slug":"usdt","cat":"stablecoins","en":"USDT (Tether)","contentLocale":"id","term":"USDT (Tether)","aka":["Tether","USDT","tether USD"],"short":"USDT adalah stablecoin yang diterbitkan Tether dan dirancang bernilai 1 dolar AS, serta menjadi stablecoin dengan peredaran terbesar dan pasangan perdagangan paling umum di exchange kripto.","body":[["Tether menyatakan setiap USDT didukung cadangan, sebagian besar berupa surat utang pemerintah AS jangka pendek, kas, dan aset lain, dan menerbitkan laporan atestasi cadangan secara berkala. Pengguna terverifikasi tertentu bisa mencetak atau menukarkan USDT langsung ke Tether, sementara kebanyakan orang membeli dan menjualnya di exchange atau ",["P2P","p2p-trading"],"."],["USDT tersedia di banyak jaringan, antara lain ",["Ethereum","ethereum"]," (ERC20), Tron (TRC20), dan sejumlah jaringan lain. Token di setiap jaringan bernilai sama tetapi tidak saling kompatibel secara langsung, jadi jaringan pengirim dan penerima harus sama. TRC20 populer untuk transfer karena biayanya umumnya rendah."],["Risiko yang perlu dipahami: USDT tidak sama dengan rekening dolar di bank. Nilainya bergantung pada kepercayaan terhadap cadangan Tether, dan Tether dapat membekukan alamat tertentu, misalnya atas permintaan penegak hukum. Di beberapa wilayah, seperti Uni Eropa di bawah ",["MiCA","mica"],", sejumlah exchange membatasi layanan USDT. Di Indonesia, USDT diperdagangkan terhadap rupiah di exchange lokal."]],"example":["Misalnya Anda membeli 500 USDT di exchange lokal dengan kurs contoh 16.200 rupiah per USDT, total 8.100.000 rupiah. Anda lalu menariknya ke exchange global lewat TRC20 dengan ",["biaya penarikan","withdrawal-fee"]," contoh 1 USDT, sehingga tiba 499 USDT. Di sana Anda bisa langsung memakai 499 USDT untuk membeli koin di pasangan spot berbasis USDT tanpa menukar ke dolar sungguhan."],"mistakes":["Mengira 1 USDT pasti bisa ditukar 1 dolar oleh siapa pun kapan saja.","Memilih jaringan penarikan USDT yang tidak didukung oleh alamat tujuan.","Membeli USDT dari penjual P2P di luar platform tanpa perlindungan escrow."],"faq":[{"q":"Apakah USDT sama dengan dolar?","a":"USDT dirancang bernilai 1 dolar dan biasanya diperdagangkan sangat dekat dengan nilai itu, tetapi ia adalah token yang diterbitkan perusahaan swasta, bukan uang dolar di rekening bank."},{"q":"USDT jaringan apa yang sebaiknya dipakai?","a":"Pilih jaringan yang didukung oleh pengirim dan penerima. Bandingkan biaya penarikan di exchange Anda, lalu pastikan halaman deposit tujuan menampilkan jaringan yang sama."}],"title":"Apa itu USDT (Tether)? Arti dan cara kerjanya","description":"Pelajari arti USDT, cara Tether menjaga nilai 1 dolar, pilihan jaringan seperti TRC20 dan ERC20, serta risiko yang perlu Anda pahami.","related":[["stablecoin","Stablecoin","Stablecoin adalah aset kripto yang dirancang menjaga nilai stabil terhadap aset acuan, biasanya 1 dolar AS, seperti USDT dan USDC, sehingga dipakai sebagai alat tukar dan tempat parkir dana di pasar kripto."],["usdc","USDC (USD Coin)","USDC adalah stablecoin yang diterbitkan Circle dan dirancang bernilai 1 dolar AS, didukung cadangan kas dan surat utang pemerintah AS jangka pendek, serta banyak dipakai di DeFi dan exchange."],["blockchain-network","Jaringan deposit (pilihan chain)","Jaringan deposit adalah blockchain yang Anda pilih untuk mengirim atau menerima sebuah aset, misalnya USDT lewat Tron, Ethereum, atau BNB Smart Chain, dan pilihan ini harus sama di sisi pengirim dan penerima."],["depeg","Depeg","Depeg adalah kondisi ketika harga stablecoin atau aset yang dipatok menyimpang cukup jauh dari nilai patokannya, misalnya USDT atau USDC diperdagangkan jauh di bawah 1 dolar AS."],["p2p-trading","P2P trading (jual beli P2P)","P2P trading adalah jual beli kripto langsung antarpengguna di platform bursa, di mana pembayaran rupiah dilakukan lewat transfer bank atau e-wallet dan kripto penjual ditahan sistem escrow."]],"lesson":{"id":"E02","slug":"is-usdt-a-dollar","ep":2,"title":"Apakah USDT itu dolar? Mengapa sering muncul saat beli kripto?"},"coin":{"slug":"tether","name":"Tether","symbol":"USDT"},"tool":null,"cta":true},"synthetic-dollar":{"slug":"synthetic-dollar","cat":"stablecoins","en":"Synthetic dollar (delta-neutral stablecoin)","contentLocale":"id","term":"Dolar sintetis (synthetic dollar)","aka":["synthetic dollar","stablecoin delta-netral"],"short":"Dolar sintetis adalah token bernilai sekitar 1 dolar yang dijaga lewat posisi delta-netral, yaitu memegang aset kripto sekaligus membuka posisi short dengan ukuran sama di kontrak berjangka perpetual.","body":[["Contoh terkenal adalah USDe dari Ethena. Ketika Anda menyetor aset seperti ",["ETH","ethereum"],", protokol membuka short ",["perpetual","perpetual-futures"]," senilai ETH tersebut. Jika harga ETH naik, aset untung dan short rugi dengan jumlah hampir sama; jika ETH turun, terjadi sebaliknya. Nilai total tetap sekitar 1 dolar per token."],["Imbal hasilnya datang dari dua sumber: hadiah ",["staking","staking"]," dari aset yang dipegang dan ",["funding rate","funding-rate"],". Saat funding rate positif, pihak short menerima pembayaran dari pihak long. Inilah alasan dolar sintetis sering menawarkan imbal hasil lebih tinggi daripada ",["stablecoin","stablecoin"]," biasa."],["Risikonya berbeda dari stablecoin berbasis kas. Funding rate bisa negatif cukup lama sehingga protokol harus membayar. Ada juga risiko bursa tempat posisi short dibuka, risiko kustodian, risiko ",["likuiditas","liquidity"]," saat penarikan massal, dan risiko depeg aset jaminan. Dolar sintetis bukan tabungan bank."]],"example":"Misalkan protokol memegang 10 ETH di harga 3.000 USDT, total 30.000, dan membuka short perpetual 10 ETH. Ia menerbitkan 30.000 dolar sintetis. Jika ETH turun ke 2.700, aset turun 3.000 tetapi short untung 3.000, jadi nilainya tetap 30.000. Jika funding rate rata-rata 0,01% per 8 jam, short menerima sekitar 3 USDT per periode untuk nosional 30.000, atau 9 USDT per hari. Namun jika funding berbalik menjadi minus 0,02%, protokol justru membayar sekitar 6 USDT per periode.","mistakes":["Menganggap imbal hasil dolar sintetis tetap, padahal sangat bergantung pada funding rate.","Mengira dolar sintetis sama dengan stablecoin yang dijamin kas di bank.","Mengabaikan risiko bursa dan kustodian tempat posisi hedging disimpan."],"faq":[{"q":"Apakah USDe termasuk stablecoin?","a":"USDe sering disebut stablecoin, tetapi Ethena sendiri menyebutnya dolar sintetis karena nilainya dijaga oleh posisi hedging, bukan oleh cadangan kas. Profil risikonya berbeda dari USDT atau USDC."},{"q":"Apa yang terjadi jika funding rate negatif?","a":"Posisi short harus membayar long, sehingga imbal hasil turun dan bisa memakan dana cadangan protokol. Jika berlangsung lama, nilai cadangan bisa tertekan."}],"title":"Apa itu dolar sintetis? Stablecoin delta-netral","description":"Pahami dolar sintetis seperti USDe: cara posisi delta-netral menjaga nilai 1 dolar, sumber imbal hasil, dan risikonya.","related":[["funding-rate","Funding rate","Funding rate adalah pembayaran berkala antara trader posisi long dan short di kontrak perpetual yang menjaga harga kontrak tetap dekat dengan harga spot."],["hedging","Hedging (lindung nilai)","Hedging adalah strategi membuka posisi yang berlawanan dengan aset atau posisi yang Anda pegang untuk mengurangi risiko kerugian akibat pergerakan harga, dengan konsekuensi potensi untungnya ikut berkurang."],["stablecoin","Stablecoin","Stablecoin adalah aset kripto yang dirancang menjaga nilai stabil terhadap aset acuan, biasanya 1 dolar AS, seperti USDT dan USDC, sehingga dipakai sebagai alat tukar dan tempat parkir dana di pasar kripto."],["depeg","Depeg","Depeg adalah kondisi ketika harga stablecoin atau aset yang dipatok menyimpang cukup jauh dari nilai patokannya, misalnya USDT atau USDC diperdagangkan jauh di bawah 1 dolar AS."]],"lesson":null,"coin":{"slug":"ethena-usde","name":"Ethena USDe","symbol":"USDE"},"tool":"/funding-rates","cta":false}});
